/**
 * Precision Historical Czechoslovak Regional Features (1936-1940)
 * True organic and jagged historical frontiers matching G. Freytag & Berndt:
 * "SUDETENLAND und die neugestaltete TSCHECHO-SLOWAKEI" (1938)
 *
 * Features include:
 * - Reichsgau Sudetenland & Border Gaus (11 districts)
 * - Zaolzie / Cieszyn Silesia (annexed to Poland Oct 1938, then Reich Sep 1939)
 * - Rest-Tschechei / Bohemia & Moravia Core (12 districts -> Protectorate Mar 1939)
 * - Autonomous Slovakia / First Slovak Republic under Tiso (12 districts)
 * - Felvidek Southern Border Strip (4 districts -> First Vienna Award to Hungary Nov 1938)
 * - Subcarpathian Ruthenia: South to Hungary (1938) & North / Chust (1939)
 */

import { makeResult } from './georesolver';
import { ResolvedTerritory } from '../types';
import {
  resolveSlovakia,
  resolveFelvidek,
  resolveLittleWar,
  resolveCarpathoUkraine,
} from './slovakiaResolvers';
export {
  resolveSlovakia,
  resolveFelvidek,
  resolveLittleWar,
  resolveCarpathoUkraine,
};

// --- Dynamic Historical Resolvers ---

export type SudetenGauKey =
  | 'EGER'
  | 'AUSSIG'
  | 'TROPPAU'
  | 'BAYERISCHE_OSTMARK'
  | 'OBERDONAU'
  | 'NIEDERDONAU';

function getCzechKrajLabel(name: string): string {
  const low = name.toLowerCase();
  if (low.includes('eger') || low.includes('karlsbad') || low.includes('karlovy')) return 'Karlovarský kraj';
  if (low.includes('tachau') || low.includes('boehmerwald') && !low.includes('krummau') || low.includes('plzen') || low.includes('chods')) return 'Plzeňský kraj';
  if (low.includes('erzgebirge') || low.includes('aussig') || low.includes('usti')) return 'Ústecký kraj';
  if (low.includes('reichenberg') || low.includes('liberec')) return 'Liberecký kraj';
  if (low.includes('trautenau') || low.includes('riesengebirge') || low.includes('hradec')) return 'Hradecký kraj';
  if (low.includes('schonhengst') || low.includes('svitavy') || low.includes('pardubic')) return 'Pardubický kraj';
  if (low.includes('altvater') || low.includes('jesenik') || low.includes('olomouc') || low.includes('hana')) return 'Olomoucký kraj';
  if (low.includes('troppau') || low.includes('opava') || low.includes('ostrav') || low.includes('hlucin') || low.includes('tesin') || low.includes('zaolzie')) return 'Ostravský kraj';
  if (low.includes('krummau') || low.includes('bayerische') || low.includes('prachatice') || low.includes('jihoces') || low.includes('budejovic')) return 'Českobudějovický kraj';
  if (low.includes('suedmaehren') || low.includes('znojmo') || low.includes('brno') || low.includes('brnen')) return 'Brněnský kraj';
  if (low.includes('vysocina') || low.includes('jihlav')) return 'Jihlavský kraj';
  if (low.includes('zlin') || low.includes('valassko')) return 'Gottwaldovský kraj';
  return 'Pražský kraj';
}

// 1. Sudetenland & Reich-annexed Border Gaue: CZE (Step 0-1) -> GER (Step 2-17) -> CZE Reintegrato (Step 18+)
export function resolveSudetenland(
  s: number,
  name: string,
  _itName: string,
  deName: string,
  _note: string,
  adminGauKey: SudetenGauKey = 'EGER'
): ResolvedTerritory {
  if (s >= 23) {
    const kraj = getCzechKrajLabel(name);
    const isUranium = name.toLowerCase().includes('karlsbad') || name.toLowerCase().includes('jachymov');
    return makeResult(
      'CZE',
      `${name} (${kraj} — Cecoslovacchia Socialista, Riforma Amministrativa 1949)`,
      isUranium
        ? `Dal 1° gennaio 1949 la riforma amministrativa della Repubblica Cecoslovacca sopprime le province storiche istituendo il ${kraj}. Nel bacino di Jáchymov e Karlovy Vary lo sfruttamento intensivo dell'uranio rifornisce il programma nucleare sovietico, mentre lungo il confine occidentale sorge la Cortina di Ferro.`
        : `Dal 1° gennaio 1949 la riforma territoriale comunista abolisce le antiche Země istituendo il ${kraj}. Completata l'espulsione della popolazione tedesca (Odsun) e avviato il ripopolamento (Dosidlování) insieme alla collettivizzazione e al presidio della Cortina di Ferro lungo il confine tedesco-austriaco.`,
      'Comintern',
      `Československá republika — ${kraj} (Prezident Klement Gottwald · KSČ)`
    );
  }
  if (s >= 21) {
    return makeResult(
      'CZE',
      `${name} (Pohraničí — Repubblica Cecoslovacca Socialista / Colpo di Praga del Febbraio 1948)`,
      "Dopo il colpo di Stato comunista di Praga (25 febbraio 1948), l'adozione della Costituzione del 9 maggio e l'elezione di Klement Gottwald alla Presidenza della Repubblica (14 giugno 1948 in seguito alle dimissioni di Edvard Beneš), la Repubblica Cecoslovacca (ČSR) diviene uno Stato socialista monopartitico del blocco sovietico, avviando la nazionalizzazione integrale dell'industria nei distretti di confine dei Sudeti.",
      'Comintern',
      'Československá republika (Prezident Klement Gottwald · Regime Comunista del Fronte Nazionale)'
    );
  }
  if (s >= 18) {
    return makeResult(
      'CZE',
      `${name} (Pohraničí — Reintegrato nella Repubblica Cecoslovacca)`,
      "Maggio-Settembre 1945: con la resa della Germania nazista, gli accordi della Conferenza di Potsdam e la nullità dell'Accordo di Monaco del 1938, i territori di confine dei Sudeti vengono pienamente reintegrati nella Repubblica Cecoslovacca restaurata (attuazione dei Decreti Beneš ed espulsione della popolazione tedescofona).",
      'Alleati',
      'Československá republika — Pohraniční území'
    );
  }
  if (s < 2) {
    return makeResult(
      'CZE',
      name,
      _note ? `${_note} — Československá republika (Pohraniční území fortificato)` : 'Československá republika (Pohraniční území)',
      undefined,
      'Československá republika — Pohraniční opevnění (ČSR)'
    );
  }
  const lowName = `${name} ${deName}`.toLowerCase();
  if (
    s === 17 &&
    (lowName.includes('troppau') ||
      lowName.includes('opava') ||
      lowName.includes('sudmahren') ||
      lowName.includes('südmähren') ||
      lowName.includes('suedmaehren') ||
      lowName.includes('znaim') ||
      lowName.includes('znojmo') ||
      lowName.includes('lundenburg'))
  ) {
    return makeResult(
      'SOV',
      `${name} (Liberata — Armata Rossa, Aprile 1945)`,
      '17-22 aprile 1945: le unità del 2° e 4° Fronte Ucraino sfondano nella Slesia ceca (Opava/Troppau, 22 aprile) e nella Moravia meridionale (Břeclav/Mikulov/Znojmo), ricollegandosi con il fronte austriaco.',
      'Comintern',
      'Armata Rossa — 2° & 4° Fronte Ucraino'
    );
  }
  let adminEntity = 'Deutsches Reich — Reichsgau Sudetenland';
  let reichSuffix = 'Reichsgau Sudetenland (Münchner Abkommen, Okt. 1938)';
  if (adminGauKey === 'EGER') {
    adminEntity = s >= 3 ? 'Deutsches Reich — Reichsgau Sudetenland (Reg.-Bez. Eger)' : 'Deutsches Reich — Reichsgau Sudetenland / Sudetengau (Reg.-Bez. Eger)';
    reichSuffix = 'Reichsgau Sudetenland — Regierungsbezirk Eger (Sitz Karlsbad · Münchner Abkommen 1938)';
  } else if (adminGauKey === 'AUSSIG') {
    adminEntity = 'Deutsches Reich — Reichsgau Sudetenland (Reg.-Bez. Aussig · Gauhauptstadt Reichenberg)';
    reichSuffix = 'Reichsgau Sudetenland — Regierungsbezirk Aussig / Gauhauptstadt Reichenberg (Münchner Abkommen 1938)';
  } else if (adminGauKey === 'TROPPAU') {
    adminEntity = 'Deutsches Reich — Reichsgau Sudetenland (Reg.-Bez. Troppau)';
    reichSuffix = 'Reichsgau Sudetenland — Regierungsbezirk Troppau (Münchner Abkommen 1938)';
  } else if (adminGauKey === 'BAYERISCHE_OSTMARK') {
    adminEntity = s >= 10
      ? 'Deutsches Reich — Bayern (Gau Bayreuth · Reg.-Bez. Niederbayern und Oberpfalz)'
      : 'Deutsches Reich — Bayern (Gau Bayerische Ostmark · Reg.-Bez. Niederbayern und Oberpfalz)';
    reichSuffix = 'Bayern / Gau Bayerische Ostmark — Reg.-Bez. Niederbayern und Oberpfalz (Eingliederung 1938/39)';
  } else if (adminGauKey === 'OBERDONAU') {
    adminEntity = s >= 3 ? 'Deutsches Reich — Reichsgau Oberdonau (Linz)' : 'Deutsches Reich — Land Österreich / Gau Oberdonau (Linz)';
    reichSuffix = 'Reichsgau Oberdonau (Südböhmen / Krummau und Kaplitz — Eingliederung 1938/39)';
  } else if (adminGauKey === 'NIEDERDONAU') {
    adminEntity = s >= 3 ? 'Deutsches Reich — Reichsgau Niederdonau (Wien)' : 'Deutsches Reich — Land Österreich / Gau Niederdonau (Wien)';
    reichSuffix = 'Reichsgau Niederdonau (Südmähren und Neubistritz — Eingliederung 1938/39)';
  }
  return makeResult(
    'GER',
    deName || name,
    _note ? `${_note} — ${reichSuffix}` : reichSuffix,
    'Asse',
    adminEntity
  );
}

// 1b. Hlučínsko (Hultschiner Ländchen): CZE (Step 0-1) -> GER Provinz Schlesien/Oberschlesien (Step 2-16) -> SOV (Step 17) -> CZE (Step 18+)
export function resolveHlucinsko(s: number, _name: string, _itName: string, deName: string, _note: string): ResolvedTerritory {
  if (s >= 23) {
    return makeResult(
      'CZE',
      'Hlučínsko / Hlučín (Ostravský kraj — Cecoslovacchia Socialista, 1949–1950)',
      'Dal 1° gennaio 1949 il territorio di Hlučín è integrato nell\'Ostravský kraj della Repubblica Cecoslovacca socialista.',
      'Comintern',
      'Československá republika — Ostravský kraj (Prezident Klement Gottwald · KSČ)'
    );
  }
  if (s >= 21) {
    return makeResult(
      'CZE',
      'Hlučínsko / Hlučín (Repubblica Cecoslovacca Socialista — 1948)',
      'Dopo il colpo di Stato di Praga (febbraio 1948), il distretto di Hlučín/Kravaře fa parte della Cecoslovacchia socialista (bacino industriale di Ostrava).',
      'Comintern',
      'Československá republika (Prezident Klement Gottwald · KSČ)'
    );
  }
  if (s >= 18) {
    return makeResult(
      'CZE',
      'Hlučínsko / Hlučín (Reintegrato nella Repubblica Cecoslovacca, 1945)',
      'Maggio 1945: annullata l\'annessione al Reich del 1938, il Hlučínsko (Hultschiner Ländchen) torna alla Cecoslovacchia nei confini del Trattato di Versailles (1920), ma la maggioranza della popolazione autoctona morava rimane esente dall\'espulsione di massa.',
      'Alleati',
      'Československá republika — Země Moravskoslezská (Hlučínsko)'
    );
  }
  if (s < 2) {
    return makeResult(
      'CZE',
      'Hlučínsko (Hlučín / Kravaře)',
      _note ? `${_note} — Země Moravskoslezská (ex territorio prussiano ceduto col Trattato di Versailles Art. 83, 1920)` : 'Země Moravskoslezská (ČSR)',
      undefined,
      'Československá republika — Země Moravskoslezská (Hlučínsko)'
    );
  }
  if (s === 17) {
    return makeResult(
      'SOV',
      'Hlučín / Hultschin (Liberata dall\'Armata Rossa — Offensiva di Ostrava-Opava, Aprile 1945)',
      '17–22 aprile 1945: la 60ª Armata del 4° Fronte Ucraino sfonda le fortificazioni ex-cecoslovacche lungo l\'Opava e la Linea dell\'Oder, liberando Hlučín e Kravaře prima della caduta di Moravská Ostrava.',
      'Comintern',
      'Armata Rossa — 4° Fronte Ucraino (Offensiva di Opava-Ostrava)'
    );
  }
  const oberschlesien = s >= 8;
  return makeResult(
    'GER',
    deName || 'Hultschiner Ländchen (Landkreis Ratibor)',
    _note
      ? `${_note} — Direttamente annesso alla ${oberschlesien ? 'Provinz Oberschlesien' : 'Preußische Provinz Schlesien'} (Reg.-Bez. Oppeln, Landkreis Ratibor — NON al Reichsgau Sudetenland)`
      : 'Hultschiner Ländchen — Provinz Schlesien / Reg.-Bez. Oppeln, Landkreis Ratibor',
    'Asse',
    oberschlesien
      ? 'Deutsches Reich — Preußische Provinz Oberschlesien (Reg.-Bez. Oppeln · Landkreis Ratibor)'
      : 'Deutsches Reich — Preußische Provinz Schlesien (Reg.-Bez. Oppeln · Landkreis Ratibor)'
  );
}

// 2. Zaolzie: CZE (Step 0-1) -> POL (Step 2-4) -> GER (Step 5-17) -> CZE Reintegrato (Step 18+)
export function resolveZaolzie(s: number, _name: string, _itName: string, deName: string, _note: string): ResolvedTerritory {
  if (s >= 23) {
    return makeResult(
      'CZE',
      'Český Těšín, Karviná & Bohumín (Ostravský kraj — Cecoslovacchia Socialista, 1949–1950)',
      'Dal 1° gennaio 1949 il bacino carbonifero e siderurgico di Těšín, Karviná e Bohumín confluisce nel nuovo Ostravský kraj come polo dell\'industria pesante del primo Piano Quinquennale (Pětiletka).',
      'Comintern',
      'Československá republika — Ostravský kraj (Prezident Klement Gottwald · KSČ)'
    );
  }
  if (s >= 21) {
    return makeResult(
      'CZE',
      'Český Těšín (Těšínsko / Zaolzie — Repubblica Cecoslovacca Socialista, Giugno 1948)',
      "In seguito al colpo di Stato di Praga (25 febbraio 1948) e alla Costituzione del 9 maggio 1948 sotto Klement Gottwald, il bacino carbonifero e siderurgico di Těšín/Karviná/Bohumín è integrato nel piano economico socialista cecoslovacco.",
      'Comintern',
      'Československá republika (Prezident Klement Gottwald · KSČ)'
    );
  }
  if (s >= 18) {
    return makeResult(
      'CZE',
      'Český Těšín, Karviná & Bohumín (Těšínsko / Zaolzie — Reintegrato nella Cecoslovacchia)',
      "Maggio-Settembre 1945: con la sconfitta del Reich e la liberazione della Slesia, il territorio del Zaolzie / Těšínsko (incl. Bohumín, Karviná e Třinec) viene ristabilito sotto la sovranità della Terza Repubblica Cecoslovacca ai confini antecedenti il settembre 1938.",
      'Alleati',
      'Československá republika — Země Moravskoslezská (Slezsko)'
    );
  }
  if (s < 2) {
    return makeResult(
      'CZE',
      'Český Těšín, Karviná & Bohumín (Těšínsko)',
      _note ? `${_note} — Slezsko (Československá republika)` : 'Slezsko (Československá republika)',
      undefined,
      'Československá republika — Země Moravskoslezská'
    );
  }
  if (s < 5) {
    return makeResult(
      'POL',
      'Zaolzie (Śląsk Cieszyński — Bogumin, Karwina, Cieszyn)',
      _note ? `${_note} — Autonomiczne Województwo Śląskie (Rzeczpospolita Polska)` : 'Autonomiczne Województwo Śląskie (Rzeczpospolita Polska, paź 1938)',
      'Alleati',
      'Rzeczpospolita Polska — Autonomiczne Województwo Śląskie'
    );
  }
  return makeResult(
    'GER',
    deName || 'Teschen (Oderberg und Karwin)',
    _note ? `${_note} — Landkreis Teschen (Provinz Schlesien / dal 1941 Oberschlesien)` : 'Landkreis Teschen (Gau Oberschlesien)',
    'Asse',
    s >= 8
      ? 'Deutsches Reich — Provinz Oberschlesien (Regierungsbezirk Kattowitz · Landkreis Teschen)'
      : 'Deutsches Reich — Provinz Schlesien (Regierungsbezirk Kattowitz · Landkreis Teschen)'
  );
}

// 3. Rest-Tschechei (Bohemia & Moravia): CZE (Step 0-2) -> GER Protectorate (Step 3-17) -> CZE Restaurata (Step 18+)
export function resolveRestTschechei(s: number, name: string, _itName: string, deName: string, _note: string): ResolvedTerritory {
  if (s >= 23) {
    const kraj = getCzechKrajLabel(name);
    return makeResult(
      'CZE',
      `${name} (${kraj} — Cecoslovacchia Socialista, Riforma Amministrativa 1949)`,
      `Dal 1° gennaio 1949 le antiche Země Česká e Moravskoslezská vengono abolite e sostituite dalle nuove regioni amministrative (Kraje: ${kraj}), nel quadro del primo Piano Quinquennale socialista e dell'allineamento integrale al blocco sovietico sotto il presidente Klement Gottwald.`,
      'Comintern',
      `Československá republika — ${kraj} (Prezident Klement Gottwald · KSČ)`
    );
  }
  if (s >= 21) {
    return makeResult(
      'CZE',
      `${name} (Repubblica Cecoslovacca — Colpo di Stato di Praga del 25 Febbraio & Costituzione del 9 Maggio 1948)`,
      "Tra il 20 e il 25 febbraio 1948 (Vítězný únor / Colpo di Praga) il Partito Comunista di Cecoslovacchia (KSČ) guidato da Klement Gottwald assume il monopolio del potere; dopo la morte del ministro degli esteri Jan Masaryk (10 marzo), la Costituzione del 9 maggio 1948 e le dimissioni di Edvard Beneš (7 giugno), il 14 giugno 1948 Gottwald diviene Presidente della Repubblica e Antonín Zápotocký Primo Ministro, allineando saldamente Praga all'URSS e al Cominform.",
      'Comintern',
      'Československá republika (Prezident Klement Gottwald · Premier Antonín Zápotocký — KSČ)'
    );
  }
  if (s >= 18) {
    return makeResult(
      'CZE',
      `${name} (Československá republika — Terza Repubblica Restaurata)`,
      "Maggio-Settembre 1945: con l'Insurrezione di Praga (5-9 maggio 1945) e l'offensiva dell'Armata Rossa con il 1° Corpo Cecoslovacco (Gen. Ludvík Svoboda), il Protettorato nazista di Boemia e Moravia viene cancellato. Restaurata la Terza Repubblica Cecoslovacca con il ritorno del Presidente Edvard Beneš al Castello di Hradčany.",
      'Alleati',
      'Československá republika — Země Česká a Moravskoslezská'
    );
  }
  if (s < 2) {
    return makeResult(
      'CZE',
      name,
      _note ? `${_note} — Československá republika` : 'Československá republika (Země Česká a Moravskoslezská)',
      undefined,
      'Československá republika — Země Česká a Moravskoslezská'
    );
  }
  if (s === 2) {
    return makeResult(
      'CZE',
      name,
      _note ? `${_note} — Druhá Československá republika` : 'Druhá Československá republika (Česko-Slovensko)',
      undefined,
      'Druhá Československá republika (Česko-Slovensko)'
    );
  }
  const lowName = `${name} ${deName}`.toLowerCase();
  if (s === 17 && (lowName.includes('ostrava') || lowName.includes('ostrau') || lowName.includes('brno') || lowName.includes('brünn') || lowName.includes('brunn') || lowName.includes('zlin') || lowName.includes('zlín') || lowName.includes('slovacko'))) {
    return makeResult(
      'SOV',
      `${name} (Liberata — Offensiva di Brno & Ostrava, Aprile 1945)`,
      '26-30 aprile 1945: il 2° Fronte Ucraino (Mareciallo Malinovskij) libera Brno (26 aprile) e la Moravia sud-orientale, mentre il 4° Fronte Ucraino ed il 1° Corpo Cecoslovacco espugnano Moravská Ostrava (30 aprile).',
      'Comintern',
      'Armata Rossa — 2° & 4° Fronte Ucraino'
    );
  }
  return makeResult(
    'GER',
    deName || name,
    _note ? `${_note} — Protektorat Böhmen und Mähren (15. März 1939)` : 'Protektorat Böhmen und Mähren (15. März 1939)',
    'Asse',
    'Deutsches Reich — Protektorat Böhmen und Mähren'
  );
}

